      first: { type: "leaf", leafId: "leaf-target" },
      second: { type: "leaf", leafId: "leaf-browser" },
      ratio: 0.5,
    });
    expect(targetPaneLayout.sessionIdsByLeafId["leaf-target"]).toBe("session-target");
  });
});

